from itertools import combinations

# N=5 grid (25 vertices). Adjacency is king's move (d_inf <= 1).
# We need to find the number of Independent Sets (ISs) of size >= 2.
# We model the grid points as (x, y) where 1 <= x, y <= 5.
N = 5
points = [(x, y) for x in range(1, N + 1) for y in range(1, N + 1)]
num_points = len(points)

def is_adjacent(p1, p2):
    # King's move adjacency (Chebyshev distance <= 1)
    return max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1])) <= 1

def is_independent_set(subset):
    for i in range(len(subset)):
        for j in range(i + 1, len(subset)):
            if is_adjacent(subset[i], subset[j]):
                return False
    return True

# Count ISs of size k
is_counts = {i: 0 for i in range(1, num_points + 1)}

# Iterate over all possible subsets
for k in range(1, num_points + 1):
    for subset in combinations(points, k):
        if is_independent_set(list(subset)):
            is_counts[k] += 1

# Total number of configurations P (ISs of size >= 2)
total_configurations = sum(is_counts[k] for k in range(2, num_points + 1))

print(f"Total Independent Sets (ISs): {sum(is_counts.values())}")
print(f"ISs of size 1: {is_counts[1]}")
print(f"Total Valid Configurations (P, size >= 2): {total_configurations}")

